/*
 Problem: 22. Generate Parentheses
 Language: cpp
 Runtime: 1 ms (82.88%)
 Memory: 16 MB (26.45%)
 Tags: Backtracking, Dynamic Programming, String
*/
class Solution {
public:
    vector<string> ans;

    void generate(string s, int open, int close, int n) {
        if (close == n) {
            ans.push_back(s);
            return;
        }

        if (open < n)
            generate(s + '(', open + 1, close, n);

        if (close < open)
            generate(s + ')', open, close + 1, n);
    }

    vector<string> generateParenthesis(int n) {
        ans.clear();
        generate("", 0, 0, n);
        return ans;
    }
};
